package top.rongx.agent.infra.persistence;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * 目标库自增序列对齐：把 identity / serial 序列拨到「表里最大 id」之后。
 *
 * <p><b>为什么需要</b>：旧库导入与「SQLite → PostgreSQL 搬行」都是带显式 id 的 INSERT。
 * PostgreSQL 的 {@code GENERATED BY DEFAULT AS IDENTITY} 允许显式 id，但<b>不会</b>推进底层
 * 序列；序列仍停在搬行前的值，于是应用下一次自己插入时就撞上已搬过去的行：
 * {@code duplicate key value violates unique constraint "token_usage_pkey"}。
 *
 * <p>SQLite 目标库不需要处理：给 {@code AUTOINCREMENT} 表插入显式 rowid 时，SQLite 会把
 * {@code sqlite_sequence} 抬到行内最大值，后续自增插入天然接在后面。
 *
 * <p>幂等：{@code is_called = false} + {@code MAX(id) + 1}，同一张表重复对齐结果不变；
 * 表为空时把序列置回 1。
 */
public final class IdentitySequenceSync {

    /**
     * 一张表里的自增列：identity 列（{@code is_identity='YES'}）与 serial 列
     * （默认值形如 {@code nextval(...)}）都算。
     */
    private static final String IDENTITY_COLUMNS_SQL = """
            SELECT column_name FROM information_schema.columns
            WHERE table_schema = current_schema()
              AND lower(table_name) = lower(?)
              AND (is_identity = 'YES' OR column_default LIKE 'nextval(%')
            ORDER BY ordinal_position""";

    private static final String SEQUENCE_OF_SQL = "SELECT pg_get_serial_sequence(?, ?)";

    private IdentitySequenceSync() {
    }

    /** 目标库是否有需要拨的独立序列（只有 PostgreSQL 有）。 */
    static boolean required(Connection target) throws SQLException {
        String name = target.getMetaData().getDatabaseProductName();
        return name != null && name.toLowerCase(Locale.ROOT).contains("postgres");
    }

    /**
     * 对齐一张表的全部自增列。
     *
     * <p>非 PostgreSQL 目标、没有自增列、序列查不到都静默跳过——本方法的定位是"顺手拨正"，
     * 不该因为目标库不支持而把已经成功的行复制判成失败。
     *
     * @return 实际对齐的列数
     */
    static int sync(Connection target, String table) throws SQLException {
        if (!required(target)) {
            return 0;
        }
        int synced = 0;
        for (String column : identityColumns(target, table)) {
            String sequence = sequenceName(target, table, column);
            if (sequence == null || sequence.isBlank()) {
                continue;
            }
            try (PreparedStatement statement = target.prepareStatement(setvalSql(table, column))) {
                statement.setString(1, sequence);
                statement.execute();
            }
            synced++;
        }
        return synced;
    }

    /**
     * 拨正语句：{@code setval(seq, MAX(col) + 1, false)}。
     *
     * <p>{@code false} 表示"下一个 nextval 就返回这个值"，因此 {@code MAX + 1} 正是应用
     * 下一次插入应该拿到的 id；表为空时 {@code COALESCE(..., 0) + 1 = 1}。
     * 表名/列名来自库元数据，仍统一加引号，避免大小写与保留字踩坑。
     */
    static String setvalSql(String table, String column) {
        return "SELECT setval(?::regclass, COALESCE((SELECT MAX(" + quote(column) + ") FROM "
                + quote(table) + "), 0) + 1, false)";
    }

    private static List<String> identityColumns(Connection target, String table) throws SQLException {
        List<String> columns = new ArrayList<>();
        try (PreparedStatement statement = target.prepareStatement(IDENTITY_COLUMNS_SQL)) {
            statement.setString(1, table);
            try (ResultSet rs = statement.executeQuery()) {
                while (rs.next()) {
                    columns.add(rs.getString(1));
                }
            }
        }
        return columns;
    }

    private static String sequenceName(Connection target, String table, String column)
            throws SQLException {
        try (PreparedStatement statement = target.prepareStatement(SEQUENCE_OF_SQL)) {
            statement.setString(1, table);
            statement.setString(2, column);
            try (ResultSet rs = statement.executeQuery()) {
                return rs.next() ? rs.getString(1) : null;
            }
        }
    }

    private static String quote(String identifier) {
        return '"' + identifier.replace("\"", "\"\"") + '"';
    }
}
